+        inscricoes: inscricoes.corpo.map(({ participanteId, status, convocadaAte }) => ({ participanteId, status, convocadaAte })),
+      });
+    }
+
+    expect(estados[1]).toEqual(estados[0]);
+    expect(estados[2]).toEqual(estados[0]);
+  });
 });

